def seed_catalog(cur):
    if len({row[0] for row in CATALOG}) != len(CATALOG):
        raise RuntimeError("Duplicate catalog slugs")
    for slug,category,title,description,price,days,revisions in CATALOG:
        cur.execute("""INSERT INTO digital_service_packages
          (slug,category,title_ar,description_ar,price_sar,delivery_days,revision_limit,active)
          VALUES (%s,%s,%s,%s,%s,%s,%s,TRUE) ON CONFLICT (slug) DO NOTHING""",
          (slug,category,title,description,price,days,revisions))
    slugs=[row[0] for row in CATALOG]
    cur.execute("SELECT slug,active FROM digital_service_packages WHERE slug = ANY(%s)",(slugs,))
    found={slug:bool(active) for slug,active in cur.fetchall()}
    if len(found)!=len(CATALOG):
        raise RuntimeError("Incomplete catalog initialization")
    return {"present":len(found),"active":sum(found.values()),"hidden":len(found)-sum(found.values())}

def main():
    if (os.getenv("APP_ENV")!="preview"
        or os.getenv("RAILWAY_PROJECT_ID")!=SANDBOX_PROJECT_ID
        or os.getenv("MINJAZ_FULL_CATALOG_SEED")!="enabled"):
        raise SystemExit("Catalog seed permitted only in explicitly enabled MINJAZ sandbox")
    url=os.getenv("DATABASE_URL")
    if not url:raise SystemExit("DATABASE_URL required")
    with psycopg2.connect(url) as conn:
        with conn.cursor() as cur:
            result=seed_catalog(cur)
    print(f"[full-catalog] present={result['present']} active={result['active']} hidden={result['hidden']}")

if __name__=="__main__":
    main()
